package com.coffeeshop.service;import at.favre.lib.crypto.bcrypt.BCrypt;import com.coffeeshop.dto.EmployeeCommands;import com.coffeeshop.model.EmployeeModels;import com.coffeeshop.repository.EmployeeRepository;import java.util.*;public final class EmployeeService{private static final Set<String>STATES=Set.of("ACTIVE","ON_LEAVE","TERMINATED");private final EmployeeRepository repository;public EmployeeService(EmployeeRepository r){repository=Objects.requireNonNull(r);}public List<EmployeeModels.Employee>employees(String search){return repository.find(search);}public List<EmployeeModels.Role>roles(){return repository.roles();}public long saveEmployee(EmployeeCommands.SaveEmployee q){if(q==null)throw new IllegalArgumentException("Employee details are required.");String status=q.status();if(!STATES.contains(status))throw new IllegalArgumentException("Select a valid employment status.");if(q.hireDate()==null)throw new IllegalArgumentException("Hire date is required.");if("TERMINATED".equals(status)!=(q.terminationDate()!=null))throw new IllegalArgumentException("Termination date and status must be consistent.");if(q.terminationDate()!=null&&q.terminationDate().isBefore(q.hireDate()))throw new IllegalArgumentException("Termination date cannot precede hire date.");if(q.id()!=null&&(q.version()==null||q.version().length==0))throw new IllegalArgumentException("Refresh this employee and try again.");return repository.saveEmployee(new EmployeeCommands.SaveEmployee(q.id(),required(q.number(),30,"Employee number"),required(q.firstName(),100,"First name"),required(q.lastName(),100,"Last name"),optional(q.phone(),30,"Phone"),optional(q.email(),254,"Email"),optional(q.jobTitle(),100,"Job title"),q.hireDate(),q.terminationDate(),status,q.active(),q.version()));}public void setActive(EmployeeModels.Employee e,boolean active){Objects.requireNonNull(e);repository.setEmployeeActive(e.id(),active,e.version());}public void saveUser(EmployeeCommands.SaveUser q,long actor){if(q==null)throw new IllegalArgumentException("User details are required.");char[]password=q.password();try{String username=required(q.username(),100,"Username");if(q.employeeId()<=0||actor<=0)throw new IllegalArgumentException("A valid employee and administrator are required.");if(q.roleIds().isEmpty())throw new IllegalArgumentException("Select at least one role.");if(q.userId()!=null&&(q.version()==null||q.version().length==0))throw new IllegalArgumentException("Refresh this user account and try again.");if(q.userId()!=null&&q.userId()==actor&&!q.active())throw new IllegalArgumentException("You cannot deactivate your own user account.");String hash=null;if(q.userId()==null||password!=null&&password.length>0){if(password==null||password.length<6)throw new IllegalArgumentException("Password must contain at least 6 characters.");hash=BCrypt.withDefaults().hashToString(12,password);}repository.saveUser(new EmployeeCommands.SaveUser(q.userId(),q.employeeId(),username,null,q.mustChange(),q.active(),q.roleIds(),q.version()),hash,actor);}finally{if(password!=null)Arrays.fill(password,'\0');}}private static String required(String v,int max,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" is required.");String x=v.trim();if(x.length()>max)throw new IllegalArgumentException(n+" is too long.");return x;}private static String optional(String v,int max,String n){return v==null||v.isBlank()?null:required(v,max,n);}}
